from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    """Return 0 for even x and 1 for odd x, using Python's modulo semantics."""
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return parity(x) for each x in xs, computed in parallel on a thread pool.

    The result is in input order and must not depend on the number of workers.
    """
    with ThreadPoolExecutor() as executor:
        return list(executor.map(parity, xs))


def test_parity_even_and_odd() -> None:
    assert parity(0) == 0
    assert parity(4) == 0
    assert parity(7) == 1


def test_parity_negative() -> None:
    assert parity(-3) == 1
    assert parity(-4) == 0


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_single() -> None:
    assert parities([5]) == [1]


def test_parities_preserves_input_order() -> None:
    xs = [3, 2, 1, 0, 9, 8]
    assert parities(xs) == [1, 0, 1, 0, 1, 0]


def test_parities_matches_serial_map_on_large_input() -> None:
    xs = list(range(10_000))
    expected = [x % 2 for x in xs]
    assert parities(xs) == expected


def test_parities_negative_values() -> None:
    xs = [-5, -4, -1, 0, 1]
    assert parities(xs) == [1, 0, 1, 0, 1]


def test_parities_repeatable() -> None:
    xs = [i * 7 - 20 for i in range(500)]
    first = parities(xs)
    for _ in range(5):
        assert parities(xs) == first


def test_parities_does_not_mutate_input() -> None:
    xs = [1, 2, 3]
    snapshot = list(xs)
    parities(xs)
    assert xs == snapshot
